	-- plural, as words: Eldreth Seethers = {npc:11469} Eldreth Seether · Dark Runes = {item:20520} Dark Rune · Large Brilliant Shards = {item:14344} Large Brilliant Shard
	["{npc:16032} wants a {item:22224} (the Eldreth ghosts of Dire Maul West, best the Eldreth Seethers, and the invisible spectres around {npc:11496}'s prison), 4 Dark Runes (the necromancers and summoners of {area:2057}, whose gate opens to a {item:13704}: one in the group is enough; or the auction house) and 8 Large Brilliant Shards (enchanters, or the auction house)."] = "{npc:16032} quiere un {item:22224} (los fantasmas Eldreth de La Masacre Oeste, mejor los Hervidores Eldreth, y los espectros invisibles alrededor de la prisión de {npc:11496}), 4 Runas oscuras (los nigromantes e invocadores de {area:2057}, cuya puerta se abre con una {item:13704}: basta con una en el grupo; o la casa de subastas) y 8 Fragmentos brillantes grandes (encantadores, o la casa de subastas).",

	-- Step 27: The Challenge
	-- {npc:16032} Falrin Treeshaper · {item:21986} Banner of Provocation · {area:1584} Blackrock Depths
	["{npc:16032} finishes the {item:21986}: plant it in the Ring of Law in {area:1584}."] = "{npc:16032} termina el {item:21986}: plántalo en el Anillo de la Ley de {area:1584}.",

	-- Step 28: Blackrock Depths: the Ring of Law
	-- {area:1584} Blackrock Depths
	["{area:1584}: the Ring of Law"] = "{area:1584}: el Anillo de la Ley",
	-- {area:1584} Blackrock Depths · {area:254} Blackrock Mountain · {zone:1427} Searing Gorge · {zone:1428} Burning Steppes · {npc:10096} High Justice Grimstone · {item:21986} Banner of Provocation · {npc:16059} Theldren · {item:22047} Top Piece of Lord Valthalak's Amulet
	["{area:1584} is the dungeon inside {area:254}, between the {zone:1427} and the {zone:1428}; a group of five. Walk into the Ring of Law so {npc:10096} sentences you, and while he reads the sentence plant the {item:21986} in the middle of the ring. After the first wave, {npc:16059} and his gladiators come instead of the usual boss: five elites who fight like players (crowd control, dispels, no taunts). Kill them all; {npc:16059} drops the {item:22047}."] = "{area:1584} es la mazmorra dentro de {area:254}, entre {zone:1427} y {zone:1428}; para un grupo de cinco. Entra en el Anillo de la Ley para que {npc:10096} te sentencie y, mientras lee la sentencia, coloca el {item:21986} en el centro del anillo. Tras la primera oleada, en lugar del jefe habitual aparecen {npc:16059} y sus gladiadores: cinco élites que luchan como jugadores (control de masas, disipaciones, sin provocaciones). Mátalos a todos; {npc:16059} suelta el {item:22047}.",
	-- {item:21986} Banner of Provocation
	["{item:21986}, in the ring"] = "{item:21986}, en el anillo",

	-- Step 29: Anthion Harmon: Anthion's Parting Words
	-- {npc:16016} Anthion Harmon · {area:2279} Stratholme · {quest:84181} Anthion's Parting Words · {item:16682} Magister's Boots · {npc:10558} Hearthsinger Forresten · {item:16687} Magister's Leggings · {npc:10440} Baron Rivendare · {item:16689} Magister's Mantle · {npc:10508} Ras Frostwhisper · {area:2057} Scholomance
	["Back to {npc:16016} at {area:2279}'s gate (Ghost Revealer). {quest:84181} takes your {item:16682}: {npc:10558} in {area:2279} (about 14%), your {item:16687}: {npc:10440} in {area:2279} (about 11%), and your {item:16689}: {npc:10508} in {area:2057} (about 16%)."] = "De vuelta con {npc:16016} en la puerta de {area:2279} (Revelador de fantasmas). {quest:84181} se lleva tu {item:16682}: {npc:10558} en {area:2279} (aprox. 14 %), tu {item:16687}: {npc:10440} en {area:2279} (aprox. 11 %), y tu {item:16689}: {npc:10508} en {area:2057} (aprox. 16 %).",

	-- Step 32: Bodley
	-- {npc:16033} Bodley · {area:1583} Blackrock Spire · {area:254} Blackrock Mountain · {quest:8961} Three Kings of Flame · {item:21987} Incendicite of Incendius · {npc:9017} Lord Incendius · {area:1584} Blackrock Depths · {item:21988} Ember of Emberseer · {npc:9816} Pyroguard Emberseer · {item:21989} Cinder of Cynders · {npc:15206} Duke of Cynders · {zone:1451} Silithus · {item:22014} Hallowed Brazier · {faction:529} Argent Dawn
	["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}: use the Ghost Revealer there. {quest:8961} wants the {item:21987} ({npc:9017} in {area:1584}), the {item:21988} ({npc:9816} in Upper Blackrock Spire), the {item:21989} (the {npc:15206} in {zone:1451}) and a {item:22014} from the {faction:529}."] = "El fantasma de {npc:16033} está en la cornisa ante el portal de {area:1583}, en lo alto de {area:254}: usa allí el Revelador de fantasmas. {quest:8961} pide el {item:21987} ({npc:9017} en {area:1584}), el {item:21988} ({npc:9816} en la Cumbre de Roca Negra Superior), el {item:21989} (el {npc:15206} en {zone:1451}) y un {item:22014} de {faction:529}.",

	-- Step 34: Honored with the Argent Dawn
	-- {faction:529} Argent Dawn
	["Honored with the {faction:529}"] = "Honorable con {faction:529}",
	-- {item:22014} Hallowed Brazier · {item:12846} Argent Dawn Commission · {npc:10840} Argent Officer Pureheart · {area:3197} Chillwind Camp · {npc:10839} Argent Officer Garush · {npc:11039} Duke Nicholas Zverenhoff · {area:2268} Light's Hope Chapel · {area:2279} Stratholme · {area:2057} Scholomance
	["The {item:22014} is sold only to Honored. Take the {item:12846} ({npc:10840} at {area:3197}, {npc:10839} at the Bulwark, or {npc:11039} at {area:2268}) and wear it: Scourgestones then drop from the Scourge, and the Argent officers take them back for reputation. Every Scourge kill in the Plaguelands counts, {area:2279}'s and {area:2057}'s undead give 5 each up to Honored, and {area:2268}'s dungeon quests give 100-200 each. Polestar's Argent Dawn Reputation guide (Reputation) walks it step by step."] = "El {item:22014} solo se vende a partir de Honorable. Toma el {item:12846} ({npc:10840} en {area:3197}, {npc:10839} en el Baluarte o {npc:11039} en {area:2268}) y llévalo puesto: así la Plaga suelta piedras de la Plaga, y los oficiales Argenta las aceptan a cambio de reputación. Cuenta cada muerte de la Plaga en las Tierras de la Peste; los no-muertos de {area:2279} y {area:2057} dan 5 cada uno hasta Honorable, y las misiones de mazmorra de {area:2268} dan 100-200 cada una. La guía de reputación con El Alba Argenta de Polestar (Reputación) te lleva paso a paso.",

	-- Step 35: Hallowed Brazier
	-- {object:2160} The Argent Dawn · {area:2268} Light's Hope Chapel · {area:3197} Chillwind Camp
	["{object:2160} quartermasters ({area:2268}, {area:3197}, the Bulwark) sell it: 133 gold 33 silver, less with your reputation discount."] = "Los intendentes de {object:2160} ({area:2268}, {area:3197}, el Baluarte) lo venden: 133 oro 33 plata, menos con tu descuento de reputación.",

	-- Step 36: Blackrock Depths and Upper Blackrock Spire
	-- {area:1584} Blackrock Depths
	["{area:1584} and Upper Blackrock Spire"] = "{area:1584} y la Cumbre de Roca Negra Superior",
	-- {npc:9017} Lord Incendius · {object:174825} Black Anvil (no name in this language: may be words) · {area:1584} Blackrock Depths · {npc:9816} Pyroguard Emberseer
	["{npc:9017} guards the {object:174825} in {area:1584} (a group of five). {npc:9816} is the first boss of Upper Blackrock Spire, a group of up to ten. Each player with the quest loots their own."] = "{npc:9017} guarda el {object:174825} en {area:1584} (un grupo de cinco). {npc:9816} es el primer jefe de la Cumbre de Roca Negra Superior, un grupo de hasta diez. Cada jugador con la misión despoja el suyo.",
	-- {npc:9816} Pyroguard Emberseer
	["{npc:9816}, Upper Blackrock Spire"] = "{npc:9816}, Cumbre de Roca Negra Superior",

	-- Step 37: Duke of Cynders
	-- {zone:1451} Silithus · {item:20422} Twilight Cultist Medallion of Station · {npc:15282} Aurel Goldleaf · {area:3425} Cenarion Hold · {item:14344} Large Brilliant Shard · {item:20432} Signet of Beckoning: Fire · {npc:15206} Duke of Cynders
	-- plural, as words: Greater Wind Stones = {object:180466} Greater Wind Stone · Abyssal Crests = {item:20513} Abyssal Crest
	["The Duke (level 62 elite, bring a group of five) only comes when someone summons him at one of the Twilight's Greater Wind Stones in {zone:1451}: the summoner wears the full Twilight Cultist set (Cowl, Mantle and Robe, from the Twilight cultists of the {zone:1451} camps), carries a {item:20422} ({npc:15282} at {area:3425}: three Abyssal Crests from summoned Templars and a {item:14344}) and a {item:20432}, which calls the {npc:15206} rather than a random Duke. Joining someone else's summon is the quick way: every player with the quest loots their own Cinder."] = "El Duque (élite de nivel 62, lleva un grupo de cinco) solo aparece cuando alguien lo invoca en una de las Piedras de viento superiores Crepusculares de {zone:1451}: quien invoca lleva el conjunto completo de cultista Crepuscular (Capucha, Manto y Toga, de los cultistas Crepusculares de los campamentos de {zone:1451}), un {item:20422} ({npc:15282} en {area:3425}: tres Blasones abisales de Templarios invocados y un {item:14344}) y un {item:20432}, que llama a {npc:15206} en vez de a un Duque al azar. Unirte a la invocación de otro es lo más rápido: cada jugador con la misión despoja su propia Ceniza.",

	-- Step 38: Bodley: Components of Importance
	-- {npc:16033} Bodley
	["{npc:16033}'s next task depends on your class: the piece the summoning brazier needs."] = "La siguiente tarea de {npc:16033} depende de tu clase: la pieza que necesita el blandón de invocación.",

	-- Step 40: Components of Importance: Druidical Remains
	-- {area:2744} Hive'Regal · {zone:1451} Silithus · {item:22226} Druidical Remains
	["At {area:2744}, the silithid hive in south-eastern {zone:1451}, the {area:2744} silithid (level 59-61 elites) drop the {item:22226} (players report anything from 5 to 50 kills). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "En {area:2744}, la colmena silítida del sureste de {zone:1451}, los silítidos de {area:2744} (élites de nivel 59-61) sueltan el {item:22226} (los jugadores hablan de entre 5 y 50 muertes). Son élites: lleva a un amigo o dos salvo que tengas buen equipo. Solo cae mientras tengas la misión; cada miembro del grupo que la tenga puede despojar uno.",

	-- Step 42: The Left Piece of Lord Valthalak's Amulet
	-- {npc:16033} Bodley · {item:22049} Brazier of Beckoning
	["{npc:16033} gives you a {item:22049}."] = "{npc:16033} te da un {item:22049}.",

	-- Step 43: The Left Piece of Lord Valthalak's Amulet: Mor Grayhoof
	-- {npc:16033} Bodley · {item:22049} Brazier of Beckoning · {npc:16080} Mor Grayhoof · {npc:9237} War Master Voone · {area:254} Blackrock Mountain
	["A dungeon run for a group of five. {npc:16033}'s {item:22049} calls {npc:16080} to {npc:9237}'s room in Lower Blackrock Spire, in {area:254}: clear the room and Voone first. Use the brazier there, kill {npc:16080} and loot the piece. He is an elite druid spirit: interrupt his heals and step out of his storm. Keep the brazier: {npc:16033} wants it back with the piece."] = "Una incursión en mazmorra para un grupo de cinco. El {item:22049} de {npc:16033} invoca a {npc:16080} en la sala de {npc:9237} en la Cumbre de Roca Negra Inferior, en {area:254}: despeja antes la sala y a Voone. Usa allí el brasero, mata a {npc:16080} y despoja la pieza. Es un espíritu de druida élite: interrumpe sus sanaciones y sal de su tormenta. Guarda el brasero: {npc:16033} lo quiere de vuelta con la pieza.",
	-- {item:22049} Brazier of Beckoning · {npc:16080} Mor Grayhoof
	["{item:22049}: summons {npc:16080}"] = "{item:22049}: invoca a {npc:16080}",

	-- Step 46: Bloodkelp
	-- {area:2079} Alcaz Island · {zone:1445} Dustwallow Marsh · {npc:16072} Tidelord Rrurgaz
	["The Strashaz naga of {area:2079}, off the north-east coast of {zone:1445}, carry it (level 59-61 elites, and {npc:16072} at 62): bring a friend or two. The Baskets of Bloodkelp on the island give 1 to 3 each without a fight. Swim over from the coast north of Theramore; elite hydras roam the water."] = "Los nagas Strashaz de {area:2079}, frente a la costa noreste de {zone:1445}, lo llevan (élites de nivel 59-61, y {npc:16072} de nivel 62): lleva a uno o dos amigos. Las Cestas de alga sangrienta de la isla dan de 1 a 3 cada una sin combatir. Ve nadando desde la costa al norte de Theramore; hay hidras élite por el agua.",

	-- Step 49: More Components of Importance: Brilliant Sword of Zealotry
	-- {area:2266} Tyr's Hand · {zone:1423} Eastern Plaguelands · {item:22228} Brilliant Sword of Zealotry
	-- plural, as words: Scarlet Praetorians = {npc:9448} Scarlet Praetorian
	["At {area:2266}, the Scarlet town in the south-east of the {zone:1423}, the Scarlet Praetorians (level 56-57 elites) of its upper courtyard drop the {item:22228} (a rare drop: up to about 50 kills). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "En {area:2266}, el pueblo Escarlata del sureste de {zone:1423}, los Pretorianos Escarlata (élites de nivel 56-57) de su patio superior sueltan el {item:22228} (botín raro: hasta unas 50 muertes). Son élites: lleva a un amigo o dos salvo que tengas buen equipo. Solo cae mientras tengas la misión; cada miembro del grupo que la tenga puede despojar uno.",

	-- Step 52: The Right Piece of Lord Valthalak's Amulet: Jarien and Sothos
	-- {quest:8991} The Right Piece of Lord Valthalak's Amulet · {npc:16101} Jarien · {npc:16102} Sothos
	["{quest:8991}: {npc:16101} and {npc:16102}"] = "{quest:8991}: {npc:16101} y {npc:16102}",
	-- {npc:16033} Bodley · {item:22051} Brazier of Beckoning · {npc:16101} Jarien · {npc:16102} Sothos · {area:2279} Stratholme · {item:21984} Left Piece of Lord Valthalak's Amulet · {item:22048} Lord Valthalak's Amulet
	["A dungeon run for a group of five. {npc:16033}'s {item:22051} calls {npc:16101} and {npc:16102} to Balnazzar's chamber at the end of {area:2279}'s Scarlet side, through the main gate: clear to it first. Use the brazier there, kill {npc:16101} and {npc:16102} and loot the piece. Both are elites: {npc:16101} cleaves, so tank him facing away; {npc:16102} fears. When one falls the other's spirit fights on. Keep the brazier: {npc:16033} wants it back with the piece. Then use the {item:21984} ({npc:16033} gave it back to you) to join the pieces into {item:22048}."] = "Una incursión en mazmorra para un grupo de cinco. El {item:22051} de {npc:16033} invoca a {npc:16101} y {npc:16102} en la cámara de Balnazzar, al final del lado Escarlata de {area:2279}, por la puerta principal: despeja antes hasta allí. Usa allí el brasero, mata a {npc:16101} y {npc:16102} y despoja la pieza. Ambos son élites: {npc:16101} da rajadas, así que tanquéalo de espaldas al grupo; {npc:16102} provoca miedo. Cuando uno cae, el espíritu del otro sigue luchando. Guarda el brasero: {npc:16033} lo quiere de vuelta con la pieza. Luego usa el {item:21984} ({npc:16033} te lo devolvió) para unir las piezas en {item:22048}.",
	-- {item:22051} Brazier of Beckoning · {npc:16101} Jarien · {npc:16102} Sothos
	["{item:22051}: summons {npc:16101} and {npc:16102}"] = "{item:22051}: invoca a {npc:16101} y {npc:16102}",
	-- {item:21984} Left Piece of Lord Valthalak's Amulet
	["{item:21984}: joins the pieces"] = "{item:21984}: une las piezas",

	-- Step 54: Final Preparations
	-- {area:1583} Blackrock Spire · {item:13512} Flask of Supreme Power
	-- plural, as words: Blackrock Bracers = {item:22138} Blackrock Bracer · Scarshield Grunts = {npc:9043} Scarshield Grunt
	["40 Blackrock Bracers from the Blackrock orcs of {area:1583} (the Scarshield Grunts in the mountain's halls outside the portal, level 53-54 elites, drop them most often; Upper {area:1583}'s orcs better than Lower's), only while you have the quest, and a {item:13512} (alchemists make it at an alchemy lab; or the auction house)."] = "40 brazales Roca Negra de los orcos Roca Negra de {area:1583} (los Gruñones Escudo de Cicatriz en las salas de la montaña fuera del portal, élites de nivel 53-54, son los que más los sueltan; los orcos de {area:1583} Superior mejor que los de la Inferior), solo mientras tengas la misión, y un {item:13512} (lo fabrican los alquimistas en un laboratorio de alquimia; o en la casa de subastas).",

	-- Step 56: Upper Blackrock Spire: Lord Valthalak
	-- {area:1583} Blackrock Spire · {npc:16042} Lord Valthalak
	["Upper {area:1583}: {npc:16042}"] = "{area:1583} Superior: {npc:16042}",
	-- {npc:10430} The Beast · {item:22056} Brazier of Beckoning · {npc:16042} Lord Valthalak · {item:22048} Lord Valthalak's Amulet · {quest:8996} Return to Bodley
	["A raid of up to ten in Upper Blackrock Spire. Clear to {npc:10430}'s room and kill {npc:10430}, then use the {item:22056} there to call {npc:16042} (level 63 boss). Kill his shades quickly; in his last phase he hits the whole room hard. Use {item:22048} on his corpse: his spirit appears. Give him the amulet, then take {quest:8996} from him."] = "Una banda de hasta diez en la Cumbre de Roca Negra Superior. Despeja hasta la sala de {npc:10430} y mata a {npc:10430}; luego usa allí el {item:22056} para invocar a {npc:16042} (jefe de nivel 63). Mata rápido a sus sombras; en su última fase golpea fuerte a toda la sala. Usa {item:22048} sobre su cadáver: aparece su espíritu. Dale el amuleto y luego acepta {quest:8996} de él.",
	-- {item:22056} Brazier of Beckoning · {npc:10430} The Beast
	["{item:22056}, in {npc:10430}'s room"] = "{item:22056}, en la sala de {npc:10430}",
	-- {item:22048} Lord Valthalak's Amulet
	["{item:22048}, on his corpse"] = "{item:22048}, en su cadáver",

	-- Step 57: Bodley: Back to the Beginning
	-- {npc:16033} Bodley · {item:22056} Brazier of Beckoning
	["Hand {npc:16033} the {item:22056}."] = "Dale a {npc:16033} el {item:22056}.",

